//! Keeps the app icon files and the app's identity consistent (E08-S05, ADR-018).
//!
//! The icon files are generated by `just icons` and committed. These checks catch a missing or stale file, and a
//! changed app ID that one of the places naming it didn't follow.
#![allow(clippy::panic, reason = "test helpers fail a test by panicking")]

use std::fs;
use std::path::{Path, PathBuf};

const APP_ID: &str = "io.github.milinpaul.Leaf";

fn crate_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
}

fn resources() -> PathBuf {
    crate_dir().join("resources")
}

fn read(path: &Path) -> Vec<u8> {
    fs::read(path).unwrap_or_else(|e| panic!("cannot read {}: {e}", path.display()))
}

/// Width and height from a PNG's header.
fn png_size(data: &[u8]) -> (u32, u32) {
    assert_eq!(&data[..8], b"\x89PNG\r\n\x1a\n", "not a PNG");
    let be = |at: usize| u32::from_be_bytes([data[at], data[at + 1], data[at + 2], data[at + 3]]);
    (be(16), be(20))
}

#[test]
fn every_png_size_exists_at_its_size() {
    for size in [16, 32, 48, 64, 128, 256, 512, 1024] {
        let png = read(&resources().join("png").join(format!("leaf-{size}.png")));
        assert_eq!(png_size(&png), (size, size), "leaf-{size}.png");
    }
}

#[test]
fn the_windows_icon_holds_sizes_up_to_256() {
    let ico = read(&resources().join("leaf.ico"));
    let word = |at: usize| u16::from_le_bytes([ico[at], ico[at + 1]]);
    let dword = |at: usize| u32::from_le_bytes([ico[at], ico[at + 1], ico[at + 2], ico[at + 3]]);
    assert_eq!((word(0), word(2)), (0, 1), "ICO header");
    let count = usize::from(word(4));
    let sizes: Vec<u32> = (0..count)
        .map(|i| {
            let entry = 6 + 16 * i;
            let (len, offset) = (dword(entry + 8), dword(entry + 12));
            let start = usize::try_from(offset).unwrap();
            let end = start + usize::try_from(len).unwrap();
            let (w, h) = png_size(&ico[start..end]);
            assert_eq!(w, h);
            // The entry's own width byte: 0 means 256.
            let declared = if ico[entry] == 0 {
                256
            } else {
                u32::from(ico[entry])
            };
            assert_eq!(declared, w, "entry {i}");
            w
        })
        .collect();
    assert!(
        sizes.contains(&16) && sizes.contains(&32) && sizes.contains(&256),
        "{sizes:?}"
    );
}

#[test]
fn the_mac_icon_is_an_icns_file() {
    let icns = read(&resources().join("Leaf.icns"));
    assert_eq!(&icns[..4], b"icns");
    let len = u32::from_be_bytes([icns[4], icns[5], icns[6], icns[7]]);
    assert_eq!(usize::try_from(len).unwrap(), icns.len());
}

#[test]
fn the_windows_resource_names_icon_1() {
    let rc = String::from_utf8(read(&resources().join("leaf.rc"))).unwrap();
    assert!(rc.contains("1 ICON \"leaf.ico\""), "GPUI loads icon resource 1");
}

#[test]
fn the_app_id_matches_everywhere() {
    let main = String::from_utf8(read(&crate_dir().join("src").join("main.rs"))).unwrap();
    assert!(main.contains(&format!("const APP_ID: &str = \"{APP_ID}\";")));

    let script = crate_dir().join("../../scripts/macos_app.py");
    let script = String::from_utf8(read(&script)).unwrap();
    assert!(script.contains(&format!("APP_ID = \"{APP_ID}\"")), "macos_app.py");

    let desktop = String::from_utf8(read(&resources().join(format!("{APP_ID}.desktop")))).unwrap();
    assert!(desktop.contains(&format!("Icon={APP_ID}")));
    assert!(desktop.contains(&format!("StartupWMClass={APP_ID}")));
}
